const ASSETS={"/manifest.webmanifest":["application/manifest+json",""],"/index.html":["text/html",""],"/icon-512.png":["image/png",""],"/api.js":["text/javascript; charset=utf-8",""],"/videos.js":["text/javascript",""],"/bola-murcha.jpg":["image/jpeg",""],"/app.js":["text/javascript; charset=utf-8",""],"/golzoom-login.js":["text/javascript",""],"/teste-videos.js":["text/javascript",""],"/icon-180.png":["image/png",""],"/icon-192.png":["image/png",""],"/teste-videos.html":["text/html",""],"/notifications.js":["text/javascript",""],"/photos.js":["text/javascript",""],"/install.js":["text/javascript",""],"/bola-cheia.jpg":["image/jpeg",""],"/sw.js":["text/javascript; charset=utf-8",""],"/vendor/pico.js":["text/javascript",""],"/vendor/LICENSE-pico.txt":["text/plain",""],"/vendor/facefinder":["application/octet-stream",""]};
const DB='https://vvampzfgjoejnwwswwek.supabase.co';
const APIKEY='sb_publishable_TVnds8HvdzfGGoIGNRRGGA_ZCd5FyOP';
const SITE='mailto:fabio_sylva@hotmail.com';
const json=(data,status=200)=>Response.json(data,{status,headers:{'Cache-Control':'no-store'}});
const b64=bytes=>btoa(String.fromCharCode(...new Uint8Array(bytes))).replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_');
export function pushEndpoint(value){try{const u=new URL(value);return u.protocol==='https:'&&!u.port&&!u.username&&!u.password&&!u.hash&&u.href.length<=2048&&(u.hostname==='fcm.googleapis.com'||u.hostname==='updates.push.services.mozilla.com'||u.hostname.endsWith('.push.services.mozilla.com')||u.hostname==='web.push.apple.com'||u.hostname.endsWith('.notify.windows.com'));}catch{return false;}}
export async function vapid(endpoint,env){
 const key=await crypto.subtle.importKey('jwk',JSON.parse(env.PUSH_PRIVATE_KEY),{name:'ECDSA',namedCurve:'P-256'},false,['sign']);
 const enc=new TextEncoder(),head=b64(enc.encode(JSON.stringify({typ:'JWT',alg:'ES256'}))),body=b64(enc.encode(JSON.stringify({aud:new URL(endpoint).origin,exp:Math.floor(Date.now()/1000)+3600,sub:SITE})));
 const input=head+'.'+body,sig=await crypto.subtle.sign({name:'ECDSA',hash:'SHA-256'},key,enc.encode(input));
 return 'vapid t='+input+'.'+b64(sig)+', k='+env.PUSH_PUBLIC_KEY;
}
async function rpc(name,body={},authorization=''){
 const r=await fetch(DB+'/rest/v1/rpc/'+name,{method:'POST',headers:{apikey:APIKEY,'Content-Type':'application/json',...(authorization?{Authorization:authorization}:{})},body:JSON.stringify(body),signal:AbortSignal.timeout(15000)});
 const text=await r.text();let data=null;if(text.trim()){try{data=JSON.parse(text);}catch{const e=Error('O servidor retornou uma resposta inesperada. Tente novamente.');e.status=502;throw e;}}if(!r.ok){const e=Error(r.status===404?'Execute o código de notificações no Supabase primeiro.':r.status===401||r.status===403?'Entre com uma conta autorizada.':data?.message||'Não foi possível concluir.');e.status=r.status===404?409:r.status;throw e;}return data;
}
async function send(endpoint,env){
 if(!pushEndpoint(endpoint))return 410;
 const r=await fetch(endpoint,{method:'POST',headers:{Authorization:await vapid(endpoint,env),TTL:'3600',Urgency:'normal',Topic:'futgordo-mensalidade'},body:new Uint8Array(0),redirect:'manual',signal:AbortSignal.timeout(10000)});return r.status;
}
async function dispatch(env){
 const targets=await rpc('claim_push_reminders',{p_secret:env.PUSH_DISPATCH_SECRET});
 let accepted=0,failed=0;
 // Bounded batches: a bad endpoint must not prevent other players' reminders.
 for(let start=0;start<targets.length;start+=5)await Promise.all(targets.slice(start,start+5).map(async t=>{
  let status=0;try{status=await send(t.endpoint,env);}catch{}
  const ok=status>=200&&status<300;if(ok)accepted++;else failed++;
  await rpc('finish_push_reminder',{p_secret:env.PUSH_DISPATCH_SECRET,p_endpoint:t.endpoint,p_day:t.reminder_day,p_lease:t.lease_id,p_status:status});
 }));return {accepted,failed};
}
// Experimental, user-triggered adapter. No password or remote session is persisted.
const GZ='https://golzoom.com';
const videoTestRuns=new Map();
export function gzDecode(s){return String(s).replace(/&quot;/g,'"').replace(/&#0*39;|&apos;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&');}
function attr(tag,name){return gzDecode(tag.match(new RegExp('(?:^|\\s)'+name+'=["\x27]([^"\x27]*)["\x27]'))?.[1]||'');}
export function gzOptions(html,field){const select=[...html.matchAll(/<select\b[^>]*>[\s\S]*?<\/select>/gi)].map(m=>m[0]).find(s=>s.includes('wire:model.live="'+field+'"'));return [...(select||'').matchAll(/<option\b([^>]*)>([\s\S]*?)<\/option>/gi)].map(m=>({value:attr(m[1],'value'),text:gzDecode(m[2].replace(/<[^>]+>/g,'').trim())}));}
export function gzClips(html,date){const clips=[];let time='';const re=/<h3\b[^>]*>([\s\S]*?)<\/h3>|<source\b([^>]+)>/gi;let m;while((m=re.exec(html))){if(m[1])time=m[1].replace(/<[^>]+>/g,'').trim();else{const src=attr(m[2],'src');if(!/^\d{2}:\d{2}:\d{2}$/.test(time)||time<'09:00:00'||time>='11:00:00'||!/^\/uploads\/[a-zA-Z0-9]+\.mp4$/.test(src))continue;clips.push({date,time,url:GZ+src});}}return clips;}
export async function searchGolzoom({email,password,date},fetcher=fetch){
 if(typeof email!=='string'||!email.includes('@')||email.length>254||typeof password!=='string'||!password||password.length>256)throw Error('Informe o e-mail e a senha do GolZoom.');
 if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||new Date(date+'T12:00:00Z').toISOString().slice(0,10)!==date||new Date(date+'T12:00:00Z').getUTCDay()!==0)throw Error('Escolha a data de um domingo.');
 let stage='abrir login';try{
 const cookies=new Map();let count=0;
 async function remote(path,init={}){
  const target=new URL(path,GZ);if(target.origin!==GZ)throw Error('Destino do GolZoom não permitido.');
  if(++count>12)throw Error('Limite de consultas atingido.');
  const r=await fetcher(target.href,{...init,redirect:'manual',headers:{Accept:'text/html,application/json',...init.headers,...(cookies.size?{Cookie:[...cookies].map(([k,v])=>k+'='+v).join('; ')}:{})},signal:AbortSignal.timeout(20000)});
  for(const value of (r.headers.getSetCookie?.()||(typeof r.headers.getAll==='function'?r.headers.getAll('Set-Cookie'):[]))){const pair=value.split(';')[0],i=pair.indexOf('=');if(i>0)cookies.set(pair.slice(0,i),pair.slice(i+1));}
  if(r.status>=300&&r.status<400){if(init.method==='POST'&&path==='/login')return r;const location=r.headers.get('Location');if(!location)throw Error('Redirecionamento inesperado do GolZoom.');return remote(location);}
  if(!r.ok){const e=Error(r.status===401||r.status===419?'Sessão do GolZoom expirou. Tente entrar novamente.':r.status===422?'GolZoom não aceitou os dados informados.':'GolZoom indisponível no momento. Tente mais tarde.');e.remoteStatus=r.status;throw e;}
  return r;
 }
 let html=await (await remote('/login')).text();const token=attr([...html.matchAll(/<input\b[^>]+>/gi)].map(m=>m[0]).find(s=>attr(s,'name')==='_token')||'','value');
 if(!token)throw Error('O formulário do GolZoom mudou. O teste foi interrompido.');
 stage='entrar no GolZoom';await remote('/login',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded',Origin:GZ,Referer:GZ+'/login'},body:new URLSearchParams({_token:token,email,password}).toString()});
 stage='confirmar sessão';password='';html=await (await remote('/videos')).text();
 if(html.includes('Digite sua senha'))throw Error('Não foi possível entrar no GolZoom. Confira seu login no site.');
 stage='ler os filtros';const component=[...html.matchAll(/<[^>]+\bwire:snapshot="([^"]+)"[^>]*>/g)].map(m=>({tag:m[0],snapshot:gzDecode(m[1])})).find(c=>{try{return Object.hasOwn(JSON.parse(c.snapshot).data,'dateSelected');}catch{return false;}});
 if(!component)throw Error('O formato dos filtros mudou. O teste foi interrompido.');
 let snapshot=component.snapshot;
 const script=[...html.matchAll(/<script\b[^>]+>/gi)].map(m=>m[0]).find(s=>s.includes('data-csrf'))||'';
 const csrf=attr(script,'data-csrf'),uri=attr(script,'data-update-uri');
 if(!csrf||uri!=='/livewire/update')throw Error('Não foi possível preparar os filtros do GolZoom.');
 async function update(updates={},calls=[]){const r=await remote(uri,{method:'POST',headers:{'Content-Type':'application/json','X-Livewire':'',Origin:GZ,Referer:GZ+'/videos'},body:JSON.stringify({_token:csrf,components:[{snapshot,updates,calls}]})});let data;try{data=await r.json();}catch{throw Error('Resposta inesperada do GolZoom.');}const c=data.components?.[0];if(!c?.snapshot||!c.effects?.html)throw Error('O GolZoom não retornou os filtros esperados.');snapshot=c.snapshot;html=c.effects.html;}
 // Only select the location/field visible to this account. Never enumerate other locations.
 stage='abrir os filtros';if(!gzOptions(html,'placeSelected').length)await update({visible:true});
 if(!gzOptions(html,'placeSelected').some(o=>o.value==='36'&&/FELLAS/i.test(o.text)))throw Error('Sua conta não tem a Quadra Fellas disponível.');
 stage='selecionar a quadra';await update({placeSelected:'36'});await update({fieldSelected:'45'});
 const label=date.split('-').reverse().join('/'),option=gzOptions(html,'dateSelected').find(o=>o.text===label);
 if(!option)return {date,clips:[],message:'Essa data não está disponível no GolZoom.'};
 stage='selecionar a data';await update({dateSelected:option.value});
 stage='buscar os horários';let clips=[];for(const hour of ['09:00','10:00']){if(hour==='10:00')await update({dateSelected:option.value});await update({},[{path:'',method:'hour_click',params:[hour]}]);clips.push(...gzClips(html,date));}
 clips=[...new Map(clips.map(c=>[c.url,c])).values()].sort((a,b)=>a.time.localeCompare(b.time));
 return {date,clips,message:clips.length?'Busca concluída. Confira os vídeos abaixo.':'Nenhum lance encontrado entre 9h e 11h.'};
 }catch(e){e.golzoomStage=stage;throw e;}
}

export default {async fetch(request,env){
 const url=new URL(request.url);
 try{
  if(url.pathname==='/api/videos/connection'){
   if(request.method!=='GET')return json({message:'Método não permitido.'},405);
   try{const r=await fetch(GZ+'/login',{redirect:'manual',signal:AbortSignal.timeout(15000)});const html=await r.text();const ready=r.ok&&html.includes('name="_token"')&&html.includes('name="email"');return json({ready,status:r.status,message:ready?'Conexão inicial disponível.':'O servidor do Futgordo não conseguiu abrir o login do GolZoom (HTTP '+r.status+'). Não é necessário informar a senha agora.'});}catch{return json({ready:false,message:'O servidor do Futgordo não conseguiu conectar ao GolZoom. Não é necessário informar a senha agora.'});}
  }
  if(url.pathname==='/api/videos/test'){
   if(request.method!=='POST')return json({message:'Método não permitido.'},405);
   if(request.headers.get('Origin')!==url.origin)return json({message:'Origem não autorizada.'},403);
   const authorization=request.headers.get('Authorization')||'';
   if(!authorization.startsWith('Bearer ')||!await rpc('is_admin',{},authorization))return json({message:'Entre no Futgordo com uma conta de ADM antes de testar.'},403);
   if(Number(request.headers.get('Content-Length')||0)>4096)return json({message:'Dados excedem o limite.'},413);
   const testKey=b64(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(authorization)));
   const now=Date.now();for(const [k,t] of videoTestRuns)if(now-t>60000)videoTestRuns.delete(k);
   if(videoTestRuns.has(testKey))return json({message:'Aguarde um minuto antes de testar novamente.'},429);
   if(videoTestRuns.size>1000)return json({message:'Teste ocupado. Tente mais tarde.'},429);
   videoTestRuns.set(testKey,now);
   const raw=await request.text();if(raw.length>4096)return json({message:'Dados excedem o limite.'},413);
   let body;try{body=JSON.parse(raw);}catch{return json({message:'Dados inválidos.'},400);}
   try{return json(await searchGolzoom(body));}catch(e){const stage=e.golzoomStage||'iniciar a busca';const status=Number.isInteger(e.remoteStatus)?' (HTTP '+e.remoteStatus+')':'';console.warn('GolZoom test failed: '+stage+status);return json({message:'A busca parou na etapa: '+stage+status+'. Nenhum dado foi salvo. Envie esta mensagem ao responsável pelo teste.'},502);}
  }
  if(url.pathname.startsWith('/api/push/')){
   if(request.method!=='POST')return json({message:'Método não permitido.'},405);
   if(!env.PUSH_PRIVATE_KEY||!env.PUSH_PUBLIC_KEY||!env.PUSH_DISPATCH_SECRET||!env.PUSH_SITE_SERVICE_TOKEN)return json({message:'Notificações aguardando configuração.'},503);
   const auth=request.headers.get('Authorization')||'';
   if(url.pathname==='/api/push/dispatch'){
    // Only the secret installed in the database scheduler can trigger a run.
    const a=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(auth));
    const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode('Bearer '+env.PUSH_DISPATCH_SECRET));
    if(new Uint8Array(a).some((v,i)=>v!==new Uint8Array(b)[i]))return json({message:'Não autorizado.'},401);
    return json(await dispatch(env));
   }
   if(!auth.startsWith('Bearer '))return json({message:'Entre na sua conta.'},401);
   if(request.headers.get('Origin')&&request.headers.get('Origin')!==url.origin)return json({message:'Origem não autorizada.'},403);
   if(url.pathname==='/api/push/setup'){
    await rpc('configure_push_service',{p_secret:env.PUSH_DISPATCH_SECRET,p_public_key:env.PUSH_PUBLIC_KEY,p_service_access:env.PUSH_SITE_SERVICE_TOKEN},auth);
    return json({ready:true});
   }
   if(url.pathname==='/api/push/test'){
    const targets=await rpc('push_test_targets',{},auth);let accepted=0;
    for(const t of targets){const status=await send(t.endpoint,env);if(status>=200&&status<300)accepted++;}
    if(!accepted)return json({message:'Nenhum celular recebeu o teste. Ative as notificações novamente.'},409);
    return json({accepted});
   }
   return json({message:'Página não encontrada.'},404);
  }
  if(!['GET','HEAD'].includes(request.method))return new Response('Método não permitido',{status:405});
  const path=url.pathname==='/'?'/index.html':url.pathname,asset=ASSETS[path];
  if(!asset)return new Response('Não encontrado',{status:404});
  const bytes=Uint8Array.from(atob(asset[1]),c=>c.charCodeAt(0));
  return new Response(request.method==='HEAD'?null:bytes,{headers:{'Content-Type':asset[0],'Cache-Control':'no-cache','X-Content-Type-Options':'nosniff',...(path==='/sw.js'?{'Service-Worker-Allowed':'/'}:{})}});
 }catch(e){return json({message:e.message||'Falha ao processar notificações.'},e.status>=400&&e.status<600?e.status:502);}
}};
